import type { InterviewQuestion } from '../questions';

type Draft = { lesson:string; topic:string; prompt:string; scenario:string; assumptions:string[]; answer:string; hinge:string; rubric:string[]; mistake:string; sources:string[]; level:1|2|3|4|5; kind:string };

// Original interview-style practice. These are authored scenarios, not claims about past interviews.
const drafts: Draft[] = [
  // Invocation and event contracts
  {lesson:'lambda-invocation-models',topic:'Invocation contracts',prompt:'A checkout API must return an order ID before the customer leaves. Sending the receipt email may take seconds. Which Lambda invocation paths would you use for each operation, and what does the API promise?',scenario:'Order persistence is customer-visible; email delivery may be delayed. A database write can succeed even if the client times out.',assumptions:['The order record is the source of truth.','Email delivery is not part of the checkout latency objective.'],answer:'Use a synchronous request path for checkout so the caller receives the order result or a defined error. Commit the order with an idempotency key before acknowledging success. Publish a durable email command after the commit, usually through an outbox or another reliable handoff, then let an asynchronous consumer deliver it. A direct asynchronous Lambda invoke only acknowledges that Lambda accepted the event; it does not mean the email was sent. State the recovery and duplicate behavior for the handoff.',hinge:'The response boundary and the work-completion boundary differ. Async acceptance is not downstream completion.',rubric:['Separates customer response from email completion','Covers commit-to-event reliability and idempotency','Defines what each acknowledgement proves'],mistake:'Returning success before the order is durable, or treating async acceptance as email delivery.',sources:['lambda-invocation-methods','lambda-event-architecture'],level:4,kind:'Architecture and service choice'},
  {lesson:'lambda-invocation-models',topic:'Event source mappings',prompt:'A team says its SQS-triggered Lambda is “pushed once per message.” Correct the model and explain how you would reason about duplicates.',scenario:'Standard SQS queue, Lambda event source mapping, batch size 10, handler writes to a database.',assumptions:['The queue and mapping use standard documented semantics.','The handler may fail after some writes have committed.'],answer:'The event source mapping polls SQS, receives messages, and invokes the function with a batch. It is not a one-time push guarantee. If the batch is not acknowledged successfully, messages can become visible again after the visibility timeout, including records whose side effects already committed. Design each record handler to be idempotent, typically with a stable event or business key and a conditional durable write. Configure visibility timeout and retry/DLQ behavior from measured function duration and recovery needs, then test partial failure.',hinge:'Delivery and business effect are different events. At-least-once delivery requires duplicate-safe effects.',rubric:['Describes polling and batching','Explains redelivery after ambiguous failure','Proposes durable idempotency and visibility/retry validation'],mistake:'Assuming a successful database write means SQS has deleted the message.',sources:['lambda-event-source-mapping','lambda-sqs-config','sqs-visibility'],level:3,kind:'Explain the internals'},
  {lesson:'lambda-invocation-models',topic:'Synchronous failure',prompt:'API Gateway calls Lambda synchronously. Lambda commits a payment, then the response times out. What should the client and backend do?',scenario:'The client cannot tell whether the payment committed. Clients may retry automatically.',assumptions:['Payment provider supports lookup by a stable merchant idempotency key.','The API may return a pending or unknown result.'],answer:'Treat the outcome as unknown, not as a definite failure. Require a client-supplied or server-issued idempotency key and persist the operation state before or with the payment call. On retry, return the existing operation result or status rather than creating another charge. The backend should reconcile provider state using the same key. Set timeouts so they bound resource use, but do not equate timeout with rollback. Expose a status lookup or pending state when completion is uncertain.',hinge:'Timeout says the caller stopped waiting; it does not prove the side effect did not happen.',rubric:['Labels the outcome ambiguous','Uses durable idempotency across client retries','Adds reconciliation/status semantics'],mistake:'Retrying with a new payment request ID after a timeout.',sources:['lambda-invocation-methods','lambda-event-architecture'],level:5,kind:'Production debugging'},
  {lesson:'lambda-invocation-models',topic:'Batch sizing',prompt:'A queue consumer takes 180 ms per record and receives batches of 10. Estimate idealized processing time, then name two reasons the real invocation may be slower.',scenario:'Records are processed sequentially; the number is a planning estimate.',assumptions:['Ignore runtime initialization for the arithmetic only.','Per-record work is independent in the simplified estimate.'],answer:'The idealized batch work is 10 × 0.18 seconds = 1.8 seconds, before invocation overhead, network variance, retries, and tail latency. If actual batch duration is much higher, inspect the slowest records, downstream latency, connection setup, and retry behavior. A larger batch can improve amortization but also increases retry blast radius and memory use. Measure p95 batch duration and queue age, then tune batch size with visibility timeout and the function timeout together.',hinge:'Average record duration gives a baseline, not a batch completion guarantee.',rubric:['Calculates 1.8 seconds with units','Names variance/overhead factors','Discusses batch size failure tradeoff and measurement'],mistake:'Using mean duration as a safe timeout with no tail margin.',sources:['lambda-event-source-mapping','lambda-sqs-config'],level:3,kind:'Numerical engineering'},
  {lesson:'lambda-invocation-models',topic:'Async acceptance and failure destination',prompt:'An asynchronous Lambda caller gets HTTP success, but the handler later fails twice. What does the caller know, and where should the team inspect failure outcomes?',scenario:'Direct asynchronous invocation with the standard retry behavior unless configured otherwise.',assumptions:['The function error is a handler error, not a caller-side synchronous error.','AWS behavior and configured destinations must be verified for the function.'],answer:'The success response means Lambda accepted the event for asynchronous processing; it does not mean the handler completed successfully. Inspect function error metrics and logs, the asynchronous invocation queue age/throttling signals, and the configured dead-letter queue or failure destination. Confirm retry settings and event age limits for this function. Make the handler idempotent because retries can repeat side effects. Alert on age and failure outcomes, not only the initial invoke response.',hinge:'Acceptance acknowledgement and execution result belong to separate stages.',rubric:['Explains acceptance-only acknowledgement','Names retry and terminal failure observability','Includes idempotency'],mistake:'Treating a 202/accepted response as proof of completed work.',sources:['lambda-invocation-methods','lambda-async-errors','lambda-monitoring'],level:4,kind:'Production debugging'},
  {lesson:'lambda-invocation-models',topic:'Event contract evolution',prompt:'A producer adds a required field to a JSON event while old queued events remain. How do you deploy the consumer safely?',scenario:'Events can be delayed for hours and replayed from a DLQ.',assumptions:['Producer and consumer deploy independently.','Old event payloads remain valid business records.'],answer:'Make the consumer tolerate both schema versions before requiring the field. Deploy that compatible consumer first, validate old and new events, then deploy the producer that emits the field. Give events an explicit schema/version or stable contract and define defaults only when the business meaning is safe. Keep DLQ replay compatible and measure unknown-version failures. If semantics cannot be inferred, route incompatible records to a quarantined path rather than silently inventing a value.',hinge:'Queue retention and replay extend the compatibility window beyond a deployment.',rubric:['Uses backward-compatible rollout order','Accounts for delayed/replayed events','Avoids unsafe defaults and adds version handling'],mistake:'Deploying a consumer that rejects payloads still present in the queue.',sources:['lambda-event-architecture','lambda-event-source-mapping'],level:4,kind:'Architecture and service choice'},
  {lesson:'lambda-invocation-models',topic:'Invocation choice under latency',prompt:'A 400 ms endpoint calls a third-party API that sometimes takes 8 seconds. The product can return “processing” and poll for status. Redesign the path and explain the contract change.',scenario:'The external service has variable latency and rate limits.',assumptions:['Client accepts eventual completion and can poll.','The operation must survive a function environment shutdown.'],answer:'Accept the request synchronously only long enough to authenticate, validate, persist an operation record, and enqueue durable work. Return an operation ID and a processing status. A worker consumes the command, applies bounded concurrency and backoff around the third-party limit, records terminal state, and supports idempotent retries. The API changes from an immediate result contract to an eventual operation resource, so define maximum age, cancellation, failure visibility, and client polling intervals. A queue smooths bursts but does not increase the provider quota.',hinge:'The architecture change is valid because the product changes the latency contract.',rubric:['Describes durable enqueue after recording operation','Protects third-party quota with bounded workers','States new client and failure semantics'],mistake:'Moving the call to async while still promising the result in 400 ms.',sources:['lambda-event-architecture','lambda-event-source-mapping'],level:5,kind:'Progressive interviewer pressure'},
  // Concurrency
  {lesson:'lambda-concurrency',topic:'Concurrency calculation',prompt:'A function receives 240 requests/second at 300 ms average duration. Estimate concurrency. What additional evidence is needed before setting reserved concurrency?',scenario:'The rate is steady for a short load-test window.',assumptions:['Use mean duration only for a first-order estimate.','Other functions share the account quota.'],answer:'The first-order estimate is 240 × 0.3 = 72 concurrent executions. This is not a safe cap by itself. Check burst shape, p95/p99 duration, retries, other account workloads, function scaling behavior, API RPS limits, and downstream budgets. Load test with realistic payloads and dependency latency. Set reserved concurrency to a deliberate share that both protects this function and leaves account capacity for other functions; monitor throttles and downstream saturation during a staged increase.',hinge:'Concurrency is rate times time in service, but safe capacity also depends on variance and shared limits.',rubric:['Computes 72','Distinguishes estimate from quota/cap','Names tail, burst, retry and dependency evidence'],mistake:'Setting the cap to 72 as if that guarantees zero throttling.',sources:['lambda-concurrency','lambda-scaling-behavior'],level:3,kind:'Numerical engineering'},
  {lesson:'lambda-concurrency',topic:'Reserved concurrency',prompt:'A latency-sensitive API and a batch importer share an account. A batch burst consumes most available concurrency. What role should reserved concurrency play, and what cost does it impose?',scenario:'The API needs predictable access to execution capacity; the importer can be delayed.',assumptions:['Both functions use standard Lambda concurrency allocation.','The API’s safe capacity is measured rather than guessed.'],answer:'Allocate a measured reserved concurrency share to the API so other functions cannot consume that allocation; this also caps the API and can cause throttling above the cap. Set an appropriate cap or separate limit for the batch worker so it cannot monopolize the account. Reserved concurrency is not pre-initialized capacity and does not eliminate cold starts. Verify account quota headroom, API RPS constraints, and the database’s safe load. Queue or schedule batch work if its completion window allows.',hinge:'Reserved concurrency is both reservation and ceiling; it protects neighbors by constraining the function too.',rubric:['Explains both guarantee and maximum','Distinguishes reserved from provisioned concurrency','Plans account and downstream budgets'],mistake:'Assuming reserved concurrency means warm environments are waiting.',sources:['lambda-concurrency'],level:4,kind:'Architecture and service choice'},
  {lesson:'lambda-concurrency',topic:'Provisioned concurrency',prompt:'A low-latency API has cold-start variance after a deployment. Would provisioned concurrency solve it completely? Design a measured rollout.',scenario:'Traffic has predictable daily peaks and a latency SLO.',assumptions:['The alias can receive provisioned concurrency.','Initialization and handler behavior are measured separately.'],answer:'Provisioned concurrency pre-initializes environments for the configured version or alias and can reduce initialization latency for traffic served within that provisioned pool. It does not make all requests latency-free: excess traffic may use on-demand capacity, handler and dependency latency remain, and deployment/version configuration must be correct. Measure cold and warm latency distributions, estimate needed capacity from peak concurrency, configure it on the routed alias, warm and validate the new version, then shift traffic gradually with rollback alarms. Include the provisioned capacity cost during idle periods.',hinge:'It addresses environment initialization for a bounded pool, not every source of latency.',rubric:['States bounded pre-initialized scope','Separates init from handler/dependency time','Provides canary and cost validation'],mistake:'Claiming provisioned concurrency removes all cold starts at any traffic level.',sources:['lambda-concurrency','lambda-aliases','lambda-deployment'],level:4,kind:'Architecture and service choice'},
  {lesson:'lambda-concurrency',topic:'RPS ceiling',prompt:'A function has a function-level concurrency quota of 800 and handles a very short request in 20 ms. A team estimates 40,000 RPS. Why is that estimate unsafe?',scenario:'Assume the current documented 10× function-level RPS quota applies to this synchronous invocation path.',assumptions:['Use 20 ms as mean duration for the concurrency estimate.','The 800 value is the applicable function-level concurrency quota.'],answer:'The concurrency arithmetic is 40,000 × 0.02 = 800 concurrent requests, so duration alone appears to fit. But the current Lambda documentation also sets the function-level request-rate quota at 10 times that concurrency quota: 800 × 10 = 8,000 RPS. The proposed 40,000 RPS therefore exceeds the RPS limit by 5× even though average concurrency is 800. Check account-level and function-level quotas, invocation path and current regional settings, then request a limit change or reshape traffic and test. Verify downstream capacity before increasing quotas.',hinge:'Both limits apply: an RPS ceiling can bind even when concurrency math appears to fit.',rubric:['Calculates 800 concurrency and 8,000 RPS quota','Identifies 40,000 RPS as five times the limit','Names exact quota checks and downstream validation'],mistake:'Treating concurrency divided by duration as the only throughput limit.',sources:['lambda-concurrency','lambda-scaling-behavior'],level:4,kind:'Numerical engineering'},
  {lesson:'lambda-concurrency',topic:'Scaling ramp',prompt:'A newly deployed function receives a sudden 15,000-request burst. The account has room, yet some requests throttle during ramp-up. What evidence and options do you consider?',scenario:'The burst arrives nearly at once rather than ramping over several minutes.',assumptions:['The function uses standard on-demand scaling.','The account concurrency quota is not exhausted.'],answer:'Check the function’s scaling behavior and throttles over time, concurrent executions, duration, region quotas, invocation source limits, and whether a deployment or downstream dependency is also constraining capacity. Account headroom alone does not imply instantaneous environment creation at arbitrary rate. Reduce burst pressure with queueing or client-side admission where the contract permits, pre-provision capacity for predictable peaks, and verify current per-function scaling limits. Test a gradual ramp and protect databases and external APIs with explicit concurrency budgets.',hinge:'Capacity may be available in quota but not provisioned instantly at the desired ramp.',rubric:['Separates account quota from scaling rate','Uses time-series evidence','Offers smoothing/pre-provisioning with downstream bounds'],mistake:'Treating available account concurrency as instantly usable burst capacity.',sources:['lambda-scaling-behavior','lambda-concurrency'],level:5,kind:'Production debugging'},
  {lesson:'lambda-concurrency',topic:'Downstream protection',prompt:'At 500 RPS and 600 ms average duration, each active invocation can hold one database connection. The database supports 180 useful connections, 30 used by other clients. Choose a defensible first concurrency limit and explain what must be validated.',scenario:'Average-duration estimate only; traffic can burst and connection use may vary.',assumptions:['Reserve 30 connections for existing clients.','No proxy multiplexing benefit is assumed without measurement.'],answer:'The remaining stated budget is 180 − 30 = 150 connections. If every active invocation holds one, a conservative initial concurrency ceiling must be below 150 to retain safety margin; choose a test value such as 100 only as an explicit starting hypothesis, not a universal answer. At 500 RPS and 0.6 seconds, unconstrained demand estimates 300 concurrent executions. That mismatch means throttling, queueing, or connection pooling is required. Measure connection hold time, query throughput, retries, tail duration, and other clients; then load test stepwise.',hinge:'The workload estimate is 300 concurrent, while the direct-connection budget is 150 before headroom.',rubric:['Calculates 300 and 150 correctly','Selects a bounded test hypothesis with headroom','Names measurements that could change the cap'],mistake:'Setting concurrency to 300 because the function can scale that far.',sources:['lambda-concurrency','lambda-rds-proxy'],level:5,kind:'Numerical engineering'},
  {lesson:'lambda-concurrency',topic:'Throttling versus errors',prompt:'CloudWatch shows Lambda throttles rising, but function error count stays flat. Explain the difference and how you investigate user impact.',scenario:'The API Gateway integration sometimes returns 429 or 5xx responses.',assumptions:['Metrics are viewed at compatible dimensions and periods.','There may be client retries.'],answer:'A throttled invocation may not start the handler, so it need not appear as a handler error. Correlate Throttles, ConcurrentExecutions, invocation source/API Gateway status codes, request rate, duration, and client retries on one timeline. Determine whether reserved concurrency, account quota, scaling rate, or an invocation-source limit binds. Check whether clients retry aggressively and amplify load. Mitigate with bounded admission, controlled backoff, or queueing if semantics permit, then validate end-user latency and accepted work rather than relying on the Lambda Errors metric alone.',hinge:'No handler error does not mean the request succeeded; throttling occurs before handler execution.',rubric:['Distinguishes throttle from handler failure','Maps to caller-visible outcomes','Checks limit owner and retry amplification'],mistake:'Using only Errors to conclude the endpoint is healthy.',sources:['lambda-concurrency','lambda-monitoring'],level:4,kind:'Production debugging'},
  // Networking
  {lesson:'lambda-networking',topic:'Private database path',prompt:'A Lambda function in private subnets cannot connect to an RDS database in the same VPC. Trace the checks in order.',scenario:'The function uses VPC configuration and DNS hostname for the database.',assumptions:['No public internet path is required for this connection.','Network ACLs may be customized.'],answer:'Confirm the function is attached to subnets in the intended VPC and that the database endpoint resolves to the expected private address. Check the Lambda security group egress and database security group ingress on the database port, allowing the function security group as source where appropriate. Verify subnet route/local VPC reachability, NACL return traffic, database status/listener, TLS/client configuration, and available connection capacity. Use VPC Flow Logs and application connection errors to distinguish timeout from refusal or DNS failure. A NAT gateway is not needed for same-VPC private database access.',hinge:'Same-VPC reachability depends on route and policy; internet egress is a separate path.',rubric:['Checks VPC/subnet and DNS','Checks both security-group directions and return path','Uses evidence to distinguish network, listener and capacity issues'],mistake:'Adding a NAT gateway to fix a security-group denial to an RDS endpoint.',sources:['lambda-vpc-config','vpc-route-tables','ec2-security-groups'],level:4,kind:'Production debugging'},
  {lesson:'lambda-networking',topic:'Internet egress',prompt:'After attaching Lambda to private subnets for RDS access, calls to a public payment API time out. Explain the likely route and a secure fix.',scenario:'The API uses a public hostname; the Lambda subnets have no direct internet route.',assumptions:['The function must reach the public provider.','The provider does not offer private connectivity in this design.'],answer:'Attaching Lambda to a VPC changes the network path. Private subnet placement alone does not provide public internet egress. Check the subnet route table for a default route through a NAT gateway in a public subnet, the NAT gateway’s route to an internet gateway, security-group egress, NACL return rules, DNS, and provider allowlists. If the call is to an AWS service with an appropriate VPC endpoint, use that private path instead. Do not place a database-facing function in a public subnet expecting a public IP to solve egress.',hinge:'Private subnet means no direct internet route; NAT or a service endpoint supplies an egress path.',rubric:['Explains path through private subnet and NAT','Checks NAT/public subnet/IGW route chain','Considers endpoint for AWS service and avoids unsafe public placement'],mistake:'Assuming Lambda receives a public IP because subnet is called public.',sources:['lambda-vpc-config','vpc-route-tables','vpc-nat-gateway','vpc-endpoints'],level:4,kind:'Explain the internals'},
  {lesson:'lambda-networking',topic:'Security group direction',prompt:'The Lambda security group allows outbound TCP 5432, and the RDS security group allows inbound TCP 5432 from the Lambda security group. Why can the connection still fail?',scenario:'The rules look correct but the application reports connection timeout.',assumptions:['Security groups are stateful.','Other network controls can still deny traffic.'],answer:'Those rules cover a common security-group path, but they do not prove reachability. Confirm both resources share connected VPC routing, the selected Lambda subnets can reach the database subnets, DNS resolves correctly, the database is listening and healthy, and NACLs permit request and ephemeral return traffic. Verify the database port and TLS requirements and inspect VPC Flow Logs. Also check connection exhaustion: a TCP handshake can work while database authentication or capacity prevents a usable session. Distinguish timeout, refusal, TLS, auth, and pool-wait errors.',hinge:'A correct pair of security-group rules is one layer of the path, not end-to-end proof.',rubric:['Explains security groups are not the whole path','Names route/NACL/DNS/database checks','Differentiates network and application-layer failures'],mistake:'Opening all ports before identifying where the connection stops.',sources:['lambda-vpc-config','vpc-security','vpc-route-tables'],level:3,kind:'Production debugging'},
  {lesson:'lambda-networking',topic:'ENI and address planning',prompt:'A Lambda workload’s concurrency rises sharply and subnet address use becomes a concern. How do you investigate without assuming one IP per invocation?',scenario:'The function is VPC-attached and uses multiple subnets.',assumptions:['Lambda manages network interfaces for VPC connectivity.','Exact ENI reuse and scaling behavior depend on current service implementation.'],answer:'Do not model one subnet address per invocation as a universal rule. Inspect available subnet IPv4 addresses, Lambda VPC configuration and service metrics/events, ENI allocation behavior documented for the current Lambda model, and other workloads sharing those subnets. Keep adequate address headroom across selected subnets and AZs, and check for creation or scaling errors. Validate with a load test that exercises environment growth. Avoid shrinking subnets or assuming unused addresses are available until ENIs from all attached services are accounted for.',hinge:'Execution concurrency and network-interface allocation are related but not a one-to-one mapping.',rubric:['Rejects simplistic one-IP-per-invoke model','Checks subnet headroom and ENI behavior evidence','Includes multi-AZ and shared-subnet accounting'],mistake:'Multiplying concurrency by one IP and declaring an exact address requirement.',sources:['lambda-vpc-config','vpc-user-guide'],level:4,kind:'Explain the internals'},
  {lesson:'lambda-networking',topic:'Private AWS service access',prompt:'A VPC-attached function uploads files to S3. The team wants to remove NAT cost. What network option can help, and what else remains to configure?',scenario:'S3 requests need to stay on AWS network paths; function also calls an external SaaS API.',assumptions:['The S3 endpoint type and routing are supported for the VPC design.','SaaS access remains public.'],answer:'Add an S3 gateway endpoint to the relevant VPC route tables and restrict its endpoint policy and bucket policy to intended resources where feasible. Confirm DNS/SDK behavior and route-table association from every Lambda subnet. This can remove the NAT path for S3 traffic, but it does not provide internet access to the external SaaS API; retain an appropriate NAT egress path or another approved connectivity design for that dependency. Measure NAT data processing and endpoint costs rather than assuming the endpoint makes all egress free.',hinge:'An endpoint supplies a private path to its service; it is not a general internet gateway.',rubric:['Names S3 gateway endpoint and route association','Includes endpoint/bucket policy and validation','Separates SaaS public egress requirement'],mistake:'Removing NAT after adding an S3 endpoint when the function still calls SaaS.',sources:['vpc-endpoints','lambda-vpc-config'],level:4,kind:'Architecture and service choice'},
  {lesson:'lambda-networking',topic:'DNS and connection failures',prompt:'A database connection works by IP but not by RDS endpoint hostname after a VPC change. What hypotheses do you test?',scenario:'The database accepts connections and a hard-coded private address is only a diagnostic clue.',assumptions:['The endpoint hostname is current and copied from the correct environment.','Hard-coded IP is not an acceptable production fix.'],answer:'Check VPC DNS support and hostnames settings, resolver configuration, DHCP options, custom DNS forwarding, and whether the function is using the expected VPC/subnets. Verify the hostname belongs to the intended database and resolves to its current address from the function’s network context. Compare DNS response and TTL with connection logs. Also check TLS hostname validation: using an IP can fail certificate identity even if TCP connects. Fix DNS/routing configuration; do not bake a database IP that can change during failover.',hinge:'Name resolution and TCP reachability are separate; IP success does not validate TLS identity or failover safety.',rubric:['Tests VPC resolver path and endpoint correctness','Separates DNS from TCP and TLS','Rejects a hard-coded IP production workaround'],mistake:'Keeping the IP workaround after failover changes the database address.',sources:['lambda-vpc-config','vpc-user-guide'],level:4,kind:'Production debugging'},
  {lesson:'lambda-networking',topic:'AZ resilience',prompt:'A VPC-attached Lambda function uses subnets in two AZs, but its database is reachable only through one AZ-specific appliance. What availability risk remains?',scenario:'The Lambda service can place execution in either selected subnet; the appliance is a shared dependency.',assumptions:['The appliance is not itself multi-AZ.','Database failover objectives are defined separately.'],answer:'Multiple Lambda subnets do not make a single-AZ appliance highly available. If traffic from an execution environment in the other AZ depends on that appliance, the appliance or its path can be a single failure point and cross-AZ routing can add latency and cost. Map each dependency path, deploy redundant appliances or use a managed multi-AZ path where suitable, and test an AZ loss. Confirm database failover and DNS behavior separately. Measure surviving capacity, not merely the count of configured subnets.',hinge:'Multi-AZ compute placement does not remove single-AZ dependency risk.',rubric:['Identifies appliance as failure-domain bottleneck','Considers cross-AZ path and latency/cost','Defines AZ failure test and surviving capacity'],mistake:'Claiming HA solely because Lambda has two configured subnets.',sources:['lambda-vpc-config','wellarchitected-review'],level:5,kind:'Progressive interviewer pressure'},
  // Configuration
  {lesson:'lambda-configuration',topic:'Memory and CPU',prompt:'A CPU-heavy image transform takes 4 seconds at 512 MB and 1.7 seconds at 2048 MB. How do you decide whether the larger setting is better?',scenario:'Same architecture, input size and code version; prices and limits depend on Region and current pricing.',assumptions:['Both runs are representative and do not hit another bottleneck.','Cold-start and warm execution are measured separately.'],answer:'Compare cost per successful transformation, not duration alone. Lambda allocates more CPU with memory, so the larger setting may lower execution time enough to reduce billed duration, but the result depends on actual pricing, memory headroom, concurrency, and downstream waits. Repeat across representative input sizes and warm/cold paths, record billed duration and max memory, and check p95 latency and error rate. Choose a setting that meets the latency objective with margin and acceptable cost; retain raw measurements and re-test after code changes.',hinge:'More memory buys resource allocation, and may reduce duration; only measured cost per useful result decides.',rubric:['Uses cost per successful operation','Mentions CPU allocation and memory headroom','Specifies representative benchmark and latency/error checks'],mistake:'Choosing 512 MB because the input object fits in 512 MB.',sources:['lambda-env-config','lambda-pricing'],level:4,kind:'Numerical engineering'},
  {lesson:'lambda-configuration',topic:'Timeout design',prompt:'A function timeout is 30 seconds. It calls a provider with a 25-second client timeout, then tries to write an audit record. What is wrong with this configuration?',scenario:'The function may be terminated at its configured timeout.',assumptions:['No durable workflow is used.','The audit write is required for correct operation.'],answer:'The provider call can consume nearly the whole invocation budget, leaving no time for cancellation, response handling, audit persistence, or cleanup. Set an overall deadline and shorter per-dependency timeouts with margin for the remaining work. Propagate cancellation where supported, record operation state durably before long work when needed, and use idempotency/reconciliation for ambiguous provider outcomes. A larger Lambda timeout alone can hide slow dependencies and increase occupied concurrency. Test the full worst-case path and align upstream timeouts and retry behavior.',hinge:'Timeouts compose; downstream timeout must leave budget for the rest of the request.',rubric:['Finds no remaining audit/cleanup budget','Defines layered deadlines with margin','Addresses ambiguous side effect and retry behavior'],mistake:'Setting Lambda timeout to 29 seconds to match provider timeout.',sources:['lambda-timeout','lambda-invocation-methods'],level:4,kind:'Code and configuration'},
  {lesson:'lambda-configuration',topic:'Ephemeral storage',prompt:'A video function downloads a 7 GB source, creates a 5 GB intermediate, then writes a 3 GB output. How do you assess `/tmp` configuration?',scenario:'The execution environment can process one file at a time, but lifecycle reuse is not guaranteed.',assumptions:['All three files may overlap during processing unless the code deletes intermediates.','The configured ephemeral-storage range and billing should be checked in current docs.'],answer:'Peak temporary disk demand can be 7 + 5 + 3 = 15 GB if all artifacts coexist, before metadata and safety margin. First redesign the pipeline to stream or delete the intermediate when safe; then size `/tmp` above measured peak scratch demand with headroom and validate supported limits and cost. Do not treat `/tmp` as durable or shared between environments. Use object storage for durable artifacts and make retries reconstruct temporary state. Monitor disk-full errors and include worst-case parallel files, not only average size.',hinge:'Temporary storage lifetime follows an environment; scratch capacity must cover simultaneous artifacts.',rubric:['Calculates 15 GB raw overlap','Considers streaming/deletion and safety margin','Separates scratch from durable object storage'],mistake:'Sizing from the 7 GB input alone while intermediates coexist.',sources:['lambda-env-config','s3-user-guide'],level:3,kind:'Numerical engineering'},
  {lesson:'lambda-configuration',topic:'Environment variables and secrets',prompt:'A developer stores a third-party API secret in a Lambda environment variable. What protections and rotation path should you review?',scenario:'The function runs in production across multiple versions.',assumptions:['The secret must be retrieved by runtime code.','Encryption at rest does not remove access-control needs.'],answer:'Treat environment configuration as sensitive data even when encrypted at rest. Limit who can read function configuration, restrict the execution role to the specific secret, use a managed secret store and a deliberate retrieval/cache strategy, and avoid logging values or putting them in error messages. Define rotation and how live versions observe the new secret. Validate KMS key permissions if customer-managed encryption is used. Consider startup retrieval latency and failure behavior; do not silently fall back to an empty or stale credential.',hinge:'Encryption at rest protects storage, but access policy and runtime exposure still matter.',rubric:['Limits configuration and secret permissions','Defines retrieval, caching and rotation behavior','Covers log leakage and failure mode'],mistake:'Assuming encrypted environment variables make broad console access harmless.',sources:['lambda-env-config','lambda-execution-role'],level:4,kind:'Architecture and service choice'},
  {lesson:'lambda-configuration',topic:'Architecture compatibility',prompt:'A Lambda package builds for ARM64 locally but fails after deployment. Give a focused compatibility investigation.',scenario:'The deployment package contains native Python dependencies.',assumptions:['The function architecture is explicitly set to arm64.','The package was built on a developer laptop.'],answer:'Check that the function architecture and artifact target the same instruction set and Linux ABI. Rebuild native dependencies for the Lambda execution environment or use a compatible container build image, inspect wheel tags and shared-library dependencies, and verify runtime version and handler path. Confirm layers use the same architecture. Reproduce with a test invocation and inspect import errors in logs. A local ARM laptop does not prove the binary targets Lambda’s runtime ABI. Promote an immutable tested artifact rather than rebuilding differently in production.',hinge:'CPU architecture alone is insufficient; operating-system ABI and runtime compatibility also matter.',rubric:['Checks architecture, ABI and native libraries','Checks layers/runtime/handler','Uses reproducible artifact and deployment test'],mistake:'Changing the Lambda architecture without rebuilding its native dependencies.',sources:['lambda-deployment','lambda-execution'],level:4,kind:'Production debugging'},
  {lesson:'lambda-configuration',topic:'Timeout and queue visibility',prompt:'An SQS-triggered Lambda has a 60-second timeout and a 90-second visibility timeout. What race can occur and how do you correct it?',scenario:'A message may still be processing when it becomes visible again.',assumptions:['The mapping follows current AWS SQS integration guidance.','Retries can run concurrently.'],answer:'The message can become visible after 90 seconds while its original function invocation is still running or before the mapping has safely completed retry handling. Another poller may receive it, causing concurrent duplicate processing. AWS currently recommends configuring the queue visibility timeout to at least six times the function timeout for this integration, plus any batching window as applicable; verify current guidance and mapping settings. Also make records idempotent, set a sensible maximum receive count/DLQ, and test slow-tail duration and throttling. Larger visibility is not a substitute for idempotency.',hinge:'Visibility controls redelivery timing; it does not prove a worker stopped.',rubric:['Identifies overlapping delivery risk','Applies current 6× guidance with config caveat','Includes idempotency and DLQ/retry validation'],mistake:'Setting visibility equal to the mean duration only.',sources:['lambda-sqs-config','lambda-sqs-errors','lambda-timeout'],level:4,kind:'Code and configuration'},
  {lesson:'lambda-configuration',topic:'Cold-start measurement',prompt:'A dashboard reports mean duration improved after increasing memory, but p99 API latency worsened. How do you investigate?',scenario:'The function is invoked through API Gateway and depends on a database.',assumptions:['Duration metric excludes some caller/network time.','Traffic mix may have changed.'],answer:'Separate Lambda initialization, handler duration, API integration/network time, and database latency. Compare p50/p95/p99 by version, memory setting, payload size and cold versus warm path; inspect Init Duration, max memory, concurrency, throttles and database connection wait. Verify traffic mix and deployment timing. Higher memory may change CPU and duration but cannot correct downstream saturation or a broader tail. Roll back only if the canary shows the regression is tied to the change, and preserve trace IDs for outliers.',hinge:'The Lambda Duration metric is not the whole request path, and mean can hide tail regression.',rubric:['Decomposes end-to-end latency','Uses percentile/version/cold-start evidence','Checks downstream path before attributing cause'],mistake:'Reading average Lambda duration as customer p99 latency.',sources:['lambda-monitoring','lambda-env-config','lambda-aliases'],level:5,kind:'Production debugging'},
  // Security
  {lesson:'lambda-security',topic:'Execution role',prompt:'A Lambda function reads one S3 prefix and writes to one DynamoDB table. What belongs in its execution role, and how do you reduce blast radius?',scenario:'The function is invoked by API Gateway and executes in the application account.',assumptions:['The function does not need to administer the bucket or table.','Resource-level permissions are supported for the required actions.'],answer:'The execution role is assumed by Lambda for the running function. Grant only required S3 read actions scoped to the object prefix and the corresponding bucket listing condition if needed, plus the exact DynamoDB table actions. Keep trust limited to the Lambda service and avoid wildcard administrative policies. The role is separate from the caller’s permission to invoke the function. Test with IAM policy simulation and CloudTrail evidence, then review denied and unused actions without broadening preemptively.',hinge:'The execution role governs what code can call; it does not decide who may invoke the function.',rubric:['Scopes actions/resources to data path','Separates runtime role from invoke permission','Includes validation and least privilege'],mistake:'Giving the function administrator access because API Gateway invokes it.',sources:['lambda-execution-role','lambda-resource-policy','iam-policy-evaluation'],level:3,kind:'Code and configuration'},
  {lesson:'lambda-security',topic:'Resource policy and cross-account invoke',prompt:'A partner in another AWS account must invoke your function. Which permission boundary must you configure, and what should the partner configure?',scenario:'The partner uses a known role and invokes one function alias.',assumptions:['The partner principal ARN is known.','Cross-account organization controls may also apply.'],answer:'The function’s resource-based policy must allow the specific partner principal to invoke the intended function or alias. The partner’s role also needs identity-based permission to call that qualified function ARN. Keep both sides least-privilege, scope to the exact account/role and alias, and consider source conditions where the integration supports them. Confirm SCPs, permissions boundaries and explicit denies. Test with the partner role and CloudTrail. An execution role policy does not grant a caller permission to invoke.',hinge:'Cross-account access needs authorization on the resource side and permission on the caller side.',rubric:['Names resource policy and caller identity policy','Scopes principal and qualified ARN','Checks organization controls and audit evidence'],mistake:'Adding S3/DynamoDB permissions to the Lambda execution role to authorize invocation.',sources:['lambda-resource-policy','lambda-execution-role','iam-policy-evaluation'],level:4,kind:'Explain the internals'},
  {lesson:'lambda-security',topic:'Confused deputy and source conditions',prompt:'An S3 bucket notification invokes a Lambda function. How do you prevent an unintended bucket or account from using the permission?',scenario:'The function resource policy grants S3 invoke permission.',assumptions:['The bucket ARN and account are known.','A service principal is used.'],answer:'Scope the Lambda resource policy to the exact S3 bucket ARN and source account, using the supported source conditions, rather than granting the S3 service principal broad invoke access. Ensure the bucket notification points to the intended function and region. Review who can alter the bucket notification and function policy, because control-plane permissions can redirect or widen the path. Test authorized and unauthorized sources, inspect CloudTrail changes, and alert on policy or notification modification.',hinge:'Service principals should be constrained to the intended resource owner and source.',rubric:['Uses source ARN/account restrictions','Reviews ability to change trigger configuration','Tests and audits both allowed and denied paths'],mistake:'Allowing any S3 bucket to invoke the function.',sources:['lambda-resource-policy','lambda-event-architecture'],level:4,kind:'Security review'},
  {lesson:'lambda-security',topic:'Secret rotation and warm environments',prompt:'A function caches a database credential in static process memory. The secret rotates, but some requests keep using the old value. Design the rotation behavior.',scenario:'Execution environments can be reused for an unknown period.',assumptions:['Credential rotation can invalidate old connections.','The function can retrieve the secret from a managed service.'],answer:'Do not assume environment reuse ends promptly after rotation. Define bounded cache lifetime or refresh on authentication failure with careful backoff, close stale connections, and ensure the secret store policy allows only this function role to read the needed secret. Coordinate rotation overlap so old and new credentials are both valid for a controlled period when the database supports it. Avoid fetching the secret on every invocation without measuring latency and service limits. Test warm environments across rotation and alarm on auth failures.',hinge:'A warm environment can preserve both a cached secret and stale connection.',rubric:['Accounts for unknown environment lifetime','Defines refresh/overlap and connection cleanup','Balances security with retrieval load and observability'],mistake:'Expecting a new deployment to immediately replace every active environment.',sources:['lambda-execution-role','lambda-env-config','lambda-deployment'],level:4,kind:'Production debugging'},
  {lesson:'lambda-security',topic:'KMS permissions',prompt:'A deployment uses a customer-managed KMS key for an encrypted secret. The function has Secrets Manager read permission but receives AccessDenied. What do you inspect?',scenario:'The secret is encrypted under a customer-managed key.',assumptions:['The secret policy and KMS key policy may both participate.','The function role is the runtime principal.'],answer:'Check the function execution role’s required Secrets Manager read action, the secret resource policy, and the KMS key policy/grant that permits decryption for the runtime principal. Verify key and secret Region/account, any encryption context conditions, permissions boundary or SCP, and CloudTrail denial details. Do not grant broad KMS decrypt on all keys. Test the exact role and secret ARN, and ensure deployment-time principals are not confused with runtime identity. If using a customer-managed key, rotation and key disablement are operational dependencies.',hinge:'Service read authorization and cryptographic key authorization are distinct checks.',rubric:['Checks role, secret policy and KMS key policy','Uses denial evidence and exact resource scope','Separates deploy-time and runtime principals'],mistake:'Adding wildcard kms:Decrypt without confirming key policy or encryption context.',sources:['lambda-execution-role','iam-policy-evaluation'],level:4,kind:'Production debugging'},
  {lesson:'lambda-security',topic:'Deployment authority',prompt:'A CI role can update function code and change the execution role ARN. Why is that more sensitive than code upload alone?',scenario:'The CI pipeline deploys to production from a protected branch.',assumptions:['The CI role is trusted by the deployment system.','The role can pass an execution role to Lambda.'],answer:'Code update authority can execute arbitrary code under the function’s runtime role. If the same principal can also change that role or pass a more privileged role, a compromised pipeline can expand its data access. Separate build, approval and deployment authority where practical; restrict iam:PassRole to the exact execution role and iam:UpdateAssumeRolePolicy or role-policy changes to a separate admin path. Protect artifacts, require review, log deployments, and use staged alias promotion with rollback.',hinge:'Deployment permission is effectively authority over the code’s runtime capabilities.',rubric:['Connects code control to runtime role power','Restricts PassRole and role mutation','Provides supply-chain and promotion controls'],mistake:'Treating CI as harmless because it cannot directly read the production database.',sources:['lambda-execution-role','lambda-deployment'],level:5,kind:'Security review'},
  {lesson:'lambda-security',topic:'VPC permissions and runtime identity',prompt:'A function has VPC access, but the security team wants to remove EC2 network-interface permissions from its role. What distinction do you investigate?',scenario:'The function uses Lambda-managed VPC networking.',assumptions:['Current Lambda service behavior and role requirements must be checked.','The role policy may have been copied from an older setup.'],answer:'Separate permissions used by the Lambda service to manage VPC networking from application permissions the function code needs at runtime. Review the current Lambda VPC documentation and execution-role guidance for required actions and whether they are needed during setup versus ongoing execution. Do not remove permissions blindly if the service still requires them for ENI management, and do not leave broad permissions without understanding their use. Inspect CloudTrail activity and test deployment, scale-out and invocation in a nonproduction environment before tightening production policy.',hinge:'Service-managed networking setup and function code access are different identities and lifecycles.',rubric:['Checks current official role guidance','Distinguishes service operations from code API calls','Validates deployment and scale-out after policy change'],mistake:'Removing a permission based only on the function source code’s API calls.',sources:['lambda-vpc-config','lambda-execution-role'],level:5,kind:'Architecture and service choice'},
  // Retries, integrations, and idempotency
  {lesson:'lambda-retries-integrations',topic:'Partial batch failure',prompt:'A batch contains 10 SQS records. Two are invalid, while eight completed side effects. How do you avoid replaying all eight successful records?',scenario:'The event source mapping supports partial batch failure responses.',assumptions:['The handler can identify each message ID.','Records are independently processable.'],answer:'Enable the SQS partial batch response feature and return only the failed item identifiers so successful messages can be deleted while failed ones become retryable. Catch per-record errors and do not report an item failed after its side effect committed unless the operation is idempotent. Configure visibility timeout, receive count and DLQ, and monitor age and failure rate. If records have ordering or cross-record dependencies, partial processing may be unsafe; model those semantics before enabling it.',hinge:'Batch-level success otherwise couples independent records into one retry unit.',rubric:['Names partial batch response and failed IDs','Requires per-record error handling and idempotency','Checks ordering and DLQ/retry configuration'],mistake:'Returning function-level failure for the whole batch after eight writes succeeded.',sources:['lambda-sqs-errors','lambda-sqs-config'],level:4,kind:'Code and configuration'},
  {lesson:'lambda-retries-integrations',topic:'Visibility timeout and duplicate overlap',prompt:'The SQS visibility timeout is shorter than a slow invocation. What can happen, and which settings and code properties work together to prevent damage?',scenario:'A message may be received by a second worker before the first attempt ends.',assumptions:['The handler sometimes exceeds its typical duration.','SQS standard queue permits duplicate delivery.'],answer:'The message can reappear while the original invocation still runs, allowing overlapping attempts and duplicate side effects. Set visibility timeout using the current Lambda/SQS integration guidance and the function timeout plus batching behavior; monitor actual tail duration. Use a durable idempotency key or conditional state transition so both workers cannot apply the business effect twice. Configure retry count and DLQ for poison messages. Revisit the worker’s timeout and dependency deadlines; simply increasing visibility can delay recovery when a worker crashes.',hinge:'Visibility bounds when another delivery may start; idempotency bounds the damage if it does.',rubric:['Describes overlapping redelivery','Aligns queue/function timeout and current guidance','Uses idempotent side effect plus terminal poison path'],mistake:'Assuming visibility timeout guarantees exactly-once processing.',sources:['lambda-sqs-config','lambda-sqs-errors','sqs-visibility'],level:4,kind:'Explain the internals'},
  {lesson:'lambda-retries-integrations',topic:'Poison records and ordering',prompt:'A stream consumer stops advancing because one record always fails. How do you preserve useful progress without silently losing ordering guarantees?',scenario:'Later records may depend on the failed record; source is an ordered stream.',assumptions:['The business ordering boundary is per key or shard and must be stated.','The failure may be deterministic data poison.'],answer:'Identify whether ordering is required across the shard or only within a partition key. Capture the failing sequence number and error, use bounded retries and an on-failure destination or quarantine strategy supported by the source, and alert on iterator age. Do not skip the record until business owners approve the resulting gap. If skipping is acceptable, persist the failed payload and reason durably before advancing; if not, repair data or code and replay in order. Tune batch behavior to contain the blast radius.',hinge:'Progress and ordering are coupled; a poison record is a data decision, not only a retry setting.',rubric:['Identifies ordering scope','Uses failure destination/quarantine with durable record','Defines whether and when skipping is permitted'],mistake:'Dropping the record to reduce iterator age without preserving it or assessing dependent events.',sources:['lambda-event-source-mapping','lambda-retry-behavior'],level:5,kind:'Production debugging'},
  {lesson:'lambda-retries-integrations',topic:'Retry ownership',prompt:'A synchronous caller retries three times, and the function’s database SDK also retries three times. A provider call fails slowly. Explain the amplification risk and a safer policy.',scenario:'Retries may be nested at multiple layers.',assumptions:['Retry counts are maxima and can occur for one logical operation.','The provider has a rate limit.'],answer:'Nested retry loops can multiply attempts: up to nine provider attempts for a single caller operation in this simplified case, plus retries from proxies or clients. This raises latency, concurrency and provider pressure. Choose a clear retry owner for each failure boundary, use bounded exponential backoff with jitter, respect retryable error classes and remaining deadline, and carry one idempotency key across all attempts. Add a circuit breaker or queue if appropriate, and measure attempt count and retry delay. Avoid retrying validation or permanent authorization failures.',hinge:'Retries compose multiplicatively when each layer retries independently.',rubric:['Explains up-to-nine amplification','Bounds retry owner/count/deadline','Includes jitter, idempotency and permanent-error handling'],mistake:'Adding retries at every layer to improve reliability independently.',sources:['lambda-retry-behavior','lambda-async-errors'],level:5,kind:'Numerical engineering'},
  {lesson:'lambda-retries-integrations',topic:'Idempotency record design',prompt:'Two duplicate events arrive concurrently with the same business key. How should the idempotency store prevent both handlers from applying the effect?',scenario:'Workers may run at the same time; a read-then-write check is possible today.',assumptions:['The store supports conditional writes or transactions.','The business effect can be associated with an operation state.'],answer:'A read-then-write check is racy: both workers can observe absence. Use an atomic conditional insert or transaction keyed by the idempotency key, recording an in-progress state and owner/lease metadata. The winner performs the effect and records the result; the loser reads the established state and returns or waits according to the contract. Define lease expiry and recovery if the winner crashes after claiming. If the side effect is outside the store, use an outbox or provider idempotency key so a crash cannot create an untracked duplicate.',hinge:'Idempotency requires atomic arbitration and recovery for a crash between claim and effect.',rubric:['Rejects non-atomic read-then-write','Describes conditional claim and result state','Covers crash recovery and external side effect'],mistake:'Writing “processed” before the effect and losing work if the process crashes.',sources:['lambda-event-architecture','lambda-event-source-mapping'],level:5,kind:'Explain the internals'},
  {lesson:'lambda-retries-integrations',topic:'Dead-letter queue operations',prompt:'A DLQ has accumulated 4,000 events after a code bug is fixed. How do you replay safely?',scenario:'Events span several schema versions and include duplicate business operations.',assumptions:['The source and destination support a controlled replay mechanism.','The original ordering may not be fully preserved by a bulk replay.'],answer:'Stop or throttle the source of new failures, inspect representative DLQ records and classify by cause/schema, then fix and test the consumer against the actual payloads. Replay in bounded batches at a rate below downstream capacity, with stable idempotency keys and monitoring for duplicate effects, age and error rate. Preserve original event identifiers and timestamps; record replay attempts. Confirm ordering requirements and whether bulk redrive changes order. Keep a quarantine path for still-invalid records instead of repeatedly cycling them.',hinge:'Replay is a production load and data operation, not a button that restores the past.',rubric:['Inspects/classifies before replay','Controls replay rate and downstream budget','Preserves identity, idempotency and residual quarantine'],mistake:'Redriving all records at once into a dependency already near capacity.',sources:['lambda-sqs-errors','sqs-visibility','lambda-event-source-mapping'],level:5,kind:'Progressive interviewer pressure'},
  {lesson:'lambda-retries-integrations',topic:'Retry after commit',prompt:'A handler writes an order row, then times out before acknowledging the SQS message. What exact invariant prevents creating a second order on redelivery?',scenario:'The SQS message can be delivered more than once.',assumptions:['Each logical order has a stable unique key.','The database supports a unique constraint or conditional write.'],answer:'Enforce uniqueness in the durable system of record, not only in process memory. Derive or carry a stable order idempotency key and use a unique constraint/conditional transaction so a redelivery either creates the order once or reads the existing order result. Make downstream effects such as email or payment follow an outbox/state machine so the database commit and message acknowledgement gap is recoverable. Verify that retries return the same business outcome and that concurrent duplicate deliveries cannot both create side effects.',hinge:'The failure window is between durable side effect and queue acknowledgement.',rubric:['Uses stable key plus atomic uniqueness','Explains commit/ack ambiguity','Covers secondary effects and concurrent duplicate test'],mistake:'Keeping a “seen message” set only in the Lambda process.',sources:['lambda-event-source-mapping','lambda-sqs-errors','lambda-event-architecture'],level:4,kind:'Architecture and service choice'},
  // Observability and deployment
  {lesson:'lambda-observability-deploy',topic:'Metric diagnosis',prompt:'Invocations stay flat, Duration p99 rises, and Errors remain low. What can this mean, and what evidence would distinguish causes?',scenario:'The Lambda fronts a database-backed API.',assumptions:['Metric period and function version dimensions are checked.','Successful but slow calls still count as successful.'],answer:'Low Errors does not imply healthy latency. The function may be waiting on a database, connection pool, external API, or lock while eventually succeeding. Compare Duration percentiles, Init Duration, concurrency, throttles, timeout proximity, logs and traces by version; inspect dependency latency, connection counts, pool wait and database CPU/locks. Check request mix and deployment timing. Set latency alarms tied to the customer SLO, and use sampled traces or structured timing spans to identify the slow segment before changing memory or concurrency.',hinge:'Error rate and latency are separate service objectives.',rubric:['Interprets slow success correctly','Correlates Lambda and dependency evidence','Uses percentiles/SLO and trace spans'],mistake:'Scaling concurrency before checking DB wait and making saturation worse.',sources:['lambda-monitoring','cloudwatch-user-guide'],level:4,kind:'Production debugging'},
  {lesson:'lambda-observability-deploy',topic:'Request correlation',prompt:'An API request triggers an asynchronous function and later an SQS worker. How do you trace one business operation across both boundaries?',scenario:'Each service emits logs and metrics; event retries may occur.',assumptions:['The operation has a stable business ID.','Sensitive personal data must not enter logs.'],answer:'Create a correlation or operation ID at the API boundary and propagate it in the durable event envelope through async invocation and SQS. Emit structured logs with that ID, event/message ID, function version, attempt and outcome, while excluding secrets and unnecessary personal data. Use trace propagation where supported but do not rely on one trace spanning long asynchronous delays. Build metrics for age, retries, failures and completion latency, and persist operation status for user-facing lookup. Test the path through retries and DLQ replay.',hinge:'Async delays and retries need durable correlation beyond a single request trace.',rubric:['Propagates stable correlation through event payload','Logs attempt/version/outcome without sensitive data','Uses durable status and queue metrics'],mistake:'Expecting an in-memory trace context to survive arbitrary queue delay and replay.',sources:['lambda-monitoring','xray-user-guide','lambda-event-architecture'],level:4,kind:'Code and configuration'},
  {lesson:'lambda-observability-deploy',topic:'Alias canary',prompt:'A new function version receives 10% of traffic and shows two errors among 20 invocations. Is that enough to roll back or promote?',scenario:'Small sample and low-volume function; a high-risk payment path.',assumptions:['Observed errors are independent only as a rough statistical assumption.','The business error severity matters.'],answer:'Twenty invocations provide weak evidence about a low error rate; two errors are a 10% observed rate and may already violate a critical business threshold, but do not precisely estimate long-run performance. Inspect error types and customer impact immediately, compare the old version and baseline, and use predeclared rollback criteria for severe failures. Increase sample size and duration to cover representative payloads and dependencies before promotion. Track latency and business outcomes as well as Lambda errors. A canary percentage alone does not guarantee a useful sample.',hinge:'Sample size and severity both matter; a small canary can reveal a catastrophic defect but cannot certify reliability.',rubric:['Interprets 2/20 as 10% observed','Separates immediate safety from statistical confidence','Uses severity-based rollback and representative exposure'],mistake:'Promoting because only two errors occurred, or waiting despite clear high-severity failures.',sources:['lambda-aliases','lambda-deployment','lambda-versions'],level:5,kind:'Numerical engineering'},
  {lesson:'lambda-observability-deploy',topic:'Version and alias routing',prompt:'A function uses an alias for production traffic, but provisioned concurrency is configured on a different qualifier. What symptoms and checks do you expect?',scenario:'The alias points to the new immutable version after deployment.',assumptions:['Provisioned concurrency is intended for production alias traffic.','Configuration is region-specific.'],answer:'Requests routed through the production alias may not use the provisioned environments configured on a different version or alias qualifier, leading to initialization latency or an initialization error depending on configuration. Inspect the alias target, provisioned concurrency qualifier/status, deployment state, and invocations by executed version. Configure capacity on the qualifier that receives traffic, wait for it to become ready, then shift traffic. Validate with traces/metrics and a canary; keep the previous version available for rollback.',hinge:'Traffic routing and warm-capacity configuration must target the same qualified version path.',rubric:['Checks alias target and provisioned qualifier alignment','Inspects readiness and executed version','Stages traffic only after capacity is ready'],mistake:'Assuming function-level capacity automatically follows every alias shift.',sources:['lambda-aliases','lambda-concurrency','lambda-versions'],level:4,kind:'Production debugging'},
  {lesson:'lambda-observability-deploy',topic:'Rollback safety',prompt:'A new version is failing because it writes a schema the old version cannot read. Alias rollback restores code but errors persist. What deployment property was missing?',scenario:'Both versions can run concurrently during a weighted rollout.',assumptions:['Database schema changes are durable and not reverted by code rollback.','Old version may still receive traffic during rollout.'],answer:'The database migration was not backward-compatible across the overlap and rollback window. Use expand-and-contract: add backward-compatible schema first, deploy code that can work with old and new shape, migrate data if needed, then remove old fields only after all old versions and consumers are gone. Alias rollback changes code routing, not database state. Test mixed-version operation and rollback with production-like data, and make schema changes observable and independently reversible where possible.',hinge:'Application rollback does not roll back an irreversible data mutation.',rubric:['Identifies schema compatibility as root issue','Explains expand-and-contract rollout','Tests mixed-version and rollback window'],mistake:'Assuming alias rollback restores the previous database schema.',sources:['lambda-deployment','lambda-aliases'],level:5,kind:'Progressive interviewer pressure'},
  {lesson:'lambda-observability-deploy',topic:'Cold-start observability',prompt:'A dashboard shows rising Init Duration but unchanged handler Duration. What deployment or workload changes could explain it?',scenario:'Traffic is low and environments are created intermittently.',assumptions:['Metric segmentation distinguishes cold initialization from handler work.','Multiple code versions may be active.'],answer:'Investigate runtime or dependency changes, larger deployment artifacts/layers, static initialization work, VPC or extension startup behavior, architecture changes, and traffic patterns that create more fresh environments. Segment by version, runtime, architecture, memory and cold/warm path; inspect initialization logs and traces. Compare deployment timestamps and package size. If latency matters, reduce unnecessary init work or provision capacity for predictable demand, then canary and measure cost. Do not optimize handler code when the observed increase is in initialization.',hinge:'Init and handler durations identify different phases and require different fixes.',rubric:['Names plausible Init contributors','Segments evidence by version/configuration','Matches mitigation to initialization rather than handler'],mistake:'Increasing handler timeout for a cold-start regression.',sources:['lambda-monitoring','lambda-execution','lambda-deployment'],level:4,kind:'Production debugging'},
  {lesson:'lambda-observability-deploy',topic:'Alert design',prompt:'Design a small set of actionable alarms for an async Lambda worker that consumes SQS and writes to a database.',scenario:'The service objective is to complete 99% of accepted work within five minutes.',assumptions:['Queue age and business completion can be measured.','A DLQ is configured.'],answer:'Alert on oldest-message age against the five-minute objective, visible backlog growth, Lambda errors/throttles, DLQ arrivals, and database saturation/latency. Add a business completion metric from accepted operation to terminal outcome because invocation success alone may not prove the record completed correctly. Use sustained evaluation periods to avoid noise, but page on DLQ or age conditions that threaten the SLO. Each alarm should name an owner and first diagnostic. Test alerts during a controlled poison-message and database-slowdown drill.',hinge:'The objective is accepted-work completion age, not function invocation count.',rubric:['Maps alarms to the stated completion SLO','Includes queue, Lambda and database symptoms','Defines action/owner and verifies via failure drill'],mistake:'Alerting only on Lambda Errors while queue age grows silently.',sources:['lambda-monitoring','lambda-sqs-errors','cloudwatch-user-guide'],level:4,kind:'Architecture and service choice'},
  // Durable functions and compute boundaries
  {lesson:'lambda-durable-models',topic:'Long elapsed time',prompt:'A workflow waits 18 hours for human approval, then runs a short function. Why is a standard Lambda invocation the wrong place to wait?',scenario:'The approval delay is unpredictable and must survive deployment and environment replacement.',assumptions:['The compute handler itself needs seconds, not hours, of CPU.','A durable workflow service or durable Lambda feature may fit after semantics review.'],answer:'A standard Lambda invocation has a bounded execution timeout and consumes an active invocation while it waits; it is not a durable sleep across deployment or environment loss. Persist workflow state and wait through a durable orchestration mechanism, then resume a short compute step when approval arrives. Evaluate Lambda durable functions or Step Functions based on workflow semantics, supported integrations, history, retries, human callback pattern and cost. Do not keep a function invocation open for 18 hours. Define timeout, cancellation and duplicate approval handling.',hinge:'Elapsed workflow duration can be long while each compute step remains short.',rubric:['Rejects long-running standard invocation','Uses persisted wait/resume orchestration','Compares durable options and handles duplicate/cancel'],mistake:'Setting a very long Lambda timeout and sleeping while holding an invocation.',sources:['lambda-durable-concepts','lambda-durable-config','lambda-fargate'],level:4,kind:'Architecture and service choice'},
  {lesson:'lambda-durable-models',topic:'Durable execution semantics',prompt:'A team assumes durable Lambda execution means every handler side effect is automatically exactly once. Correct the assumption and design a safe activity.',scenario:'A durable workflow retries an activity after a transient failure.',assumptions:['The workflow may replay or retry an activity according to its model.','The side effect targets an external payment API.'],answer:'Durable orchestration preserves workflow progress and supports waits/retries, but it does not make an external side effect exactly once by magic. Activities must be idempotent or use the provider’s idempotency mechanism, and the workflow should persist a stable operation key and result. Understand which code is replayed versus checkpointed using current durable-function semantics. Bound retries, classify permanent failures, and reconcile ambiguous timeouts with the provider. Test a crash after provider success but before activity completion is recorded.',hinge:'Durability preserves orchestration state; external side effects still need duplicate-safe design.',rubric:['Separates orchestration durability from exactly-once effect','Uses stable idempotency and reconciliation','Tests failure between side effect and checkpoint'],mistake:'Assuming durable replay cannot repeat a payment request.',sources:['lambda-durable-concepts','lambda-durable-config'],level:5,kind:'Explain the internals'},
  {lesson:'lambda-durable-models',topic:'Step Functions boundary',prompt:'You have a 12-step order workflow with branching, human review, retries, and audit requirements. When would you choose Step Functions over one large Lambda?',scenario:'Each compute step is short; the workflow lasts minutes to days.',assumptions:['Workflow state and transitions need operational visibility.','The team accepts an explicit state-machine definition.'],answer:'Step Functions is a strong candidate when orchestration itself—branching, waits, retries, compensation, execution history and operational visibility—is a first-class requirement. Keep each Lambda focused on bounded work and let the state machine coordinate it. Compare supported integrations, execution type, state-transition cost, payload/state limits and workflow duration against durable Lambda capabilities using current docs. A single large function hides progress, couples retries and makes human waits or partial recovery difficult. Preserve idempotency for activities either way.',hinge:'Choose the orchestration surface based on workflow visibility and control needs, not function count.',rubric:['Maps stated needs to explicit orchestration','Compares current feature/cost boundaries','Explains why one large handler harms recovery'],mistake:'Choosing by “serverless” label without examining workflow semantics.',sources:['lambda-durable-concepts','lambda-fargate','lambda-event-architecture'],level:4,kind:'Architecture and service choice'},
  {lesson:'lambda-durable-models',topic:'Managed Instances boundary',prompt:'A team wants Lambda but needs persistent processes and concurrency greater than one per environment. What product boundary must it investigate?',scenario:'Workload is an always-on connection-heavy service.',assumptions:['AWS Lambda Managed Instances may be available subject to current regions/runtimes/limits.','Standard Event Function behavior must not be generalized.'],answer:'Investigate Lambda Managed Instances as a distinct execution model and verify current runtime, region, networking, concurrency, scaling, lifecycle and pricing support. Standard on-demand Event Functions generally use an execution environment for one invocation at a time; do not assume Managed Instances share that model or inherit every standard behavior. Compare it with ECS/Fargate or EC2 for persistent process needs, connection reuse, host control, scale and operating burden. Prototype concurrency safety because shared-process code must handle concurrent requests correctly.',hinge:'A product name in the Lambda family does not imply identical runtime and concurrency semantics.',rubric:['Separates Managed Instances from standard Event Functions','Verifies current capability limits','Assesses thread safety and container/VM alternatives'],mistake:'Using standard Event Function concurrency assumptions for Managed Instances.',sources:['lambda-managed','lambda-fargate','lambda-concurrency'],level:5,kind:'Architecture and service choice'},
  {lesson:'lambda-durable-models',topic:'Workload boundary',prompt:'A job needs 50 minutes of CPU and writes a checkpoint every minute. Compare standard Lambda, durable Lambda, and a container/batch option.',scenario:'The job can be split at checkpoints but has sustained CPU demand.',assumptions:['Standard Lambda timeout is 15 minutes under current docs.','Exact service limits and cost must be verified for the chosen Region.'],answer:'A single standard Lambda invocation is unsuitable if its execution exceeds the documented 15-minute maximum. Durable Lambda can extend total workflow elapsed time under supported models, but it does not mean one uninterrupted 50-minute CPU invocation; checkpointed orchestration should invoke bounded activities. AWS Batch or a container service is more natural if the task needs sustained CPU, custom runtime or long process execution. Compare startup delay, checkpoint complexity, retries, throughput and total compute cost. Test recovery from each checkpoint and prevent repeated external writes.',hinge:'A durable timeline is not the same as an unbounded compute slot.',rubric:['Applies standard invocation limit with current-source caveat','Distinguishes durable wait/orchestration from CPU runtime','Compares Batch/container with checkpoint/recovery criteria'],mistake:'Assuming a one-year durable execution permits one Lambda handler to run for one year.',sources:['lambda-durable-concepts','lambda-durable-config','lambda-fargate','batch-user-guide'],level:5,kind:'Architecture and service choice'},
  {lesson:'lambda-durable-models',topic:'Durable cost model',prompt:'An approval workflow waits 10 days but executes only 30 seconds of code. How do you compare a durable orchestration design with a continuously running worker?',scenario:'There are 5,000 workflows per month and approval time is variable.',assumptions:['No current pricing values are supplied.','Pricing dimensions vary by selected service and Region.'],answer:'Separate active compute seconds from waiting duration. A continuously running worker would reserve capacity while mostly idle unless it multiplexes many workflows, increasing operational and cost burden. A durable service can persist wait state and resume work, but price depends on workflow starts, transitions/checkpoints, storage, invocations and integrations. Build a monthly model using current regional prices, expected retries and retention; include engineering and on-call cost qualitatively. Validate behavior under mass resume after an outage so thousands of workflows do not overwhelm dependencies.',hinge:'Ten days of elapsed time does not imply ten days of CPU usage.',rubric:['Separates wait time from compute time','Lists cost meters and current price inputs','Includes resume burst and operational cost'],mistake:'Multiplying 10 days by instance hourly cost without accounting for multiplexing or durable meters.',sources:['lambda-durable-concepts','lambda-pricing','batch-user-guide'],level:4,kind:'Numerical engineering'},
  {lesson:'lambda-durable-models',topic:'Workflow versioning',prompt:'A durable workflow deployment changes how stored state is interpreted. What compatibility hazards arise for executions already in progress?',scenario:'Old executions can resume after the new code is deployed.',assumptions:['Persisted workflow state may outlive a deployment.','The exact replay/version behavior is product-specific.'],answer:'In-flight executions may resume with state created by older code, so field names, step identifiers, serialization and replay semantics can become compatibility boundaries. Review current durable-function versioning guidance and test old persisted states against the candidate release. Use explicit workflow schema versions and additive changes, preserve compatible step behavior, and plan migration or drain windows for breaking changes. Deploy gradually, monitor resumed execution failures, and keep a rollback path that can interpret both state versions. Do not assume alias rollback rewrites persisted workflow state.',hinge:'Code is not the only deployed artifact; persisted orchestration state must remain readable.',rubric:['Identifies old state resuming on new code','Calls for product-specific version/replay review','Uses schema evolution and rollback compatibility'],mistake:'Testing only new executions after deployment.',sources:['lambda-durable-concepts','lambda-durable-config','lambda-versions'],level:5,kind:'Progressive interviewer pressure'},
];

export const lambdaExtraQuestions: InterviewQuestion[] = drafts.map((d,index)=>{
  const number=index+5;
  const next=number===60?5:number+1;
  const harder=number>=59?5:number+2;
  return {
    id:`L${String(number).padStart(2,'0')}`,lesson:d.lesson,unit:'03',topic:d.topic,
    difficulty:d.level===1?'Foundation':d.level===5?'Defense':'Applied',difficultyLevel:d.level,
    mode:d.kind==='Production debugging'?'Debugging':d.kind==='Explain the internals'?'Deep dive':'Decision',assessmentType:d.kind,
    prompt:d.prompt,scenario:d.scenario,assumptions:d.assumptions,answer:d.answer,
    explanation:`${d.hinge} ${d.mistake} Interview mein mechanism, assumption, risk, and evidence in order explain karo.`,
    learningObjective:`Reason about ${d.topic} in a production Lambda design.`,
    rubric:d.rubric,mistakes:[d.mistake,'State what evidence would change the recommendation.'],
    hint:`Start with the request or event boundary. Then trace ${d.topic} through the AWS execution path.`,
    followUp:'Which metric, log field, or failure test would prove this design behaves as intended?',
    sources:d.sources,concepts:[d.topic,'AWS Lambda',d.kind],
    followUps:[`L${String(next).padStart(2,'0')}`,`L${String(harder).padStart(2,'0')}`],
    prerequisites:['lambda-lifecycle',d.lesson],revisionNotes:[d.lesson]
  };
});
